CREATE TABLE IF NOT EXISTS ScheduledReports(Id INTEGER PRIMARY KEY AUTOINCREMENT,Name TEXT UNIQUE NOT NULL,ReportPath TEXT NOT NULL,ScheduleType TEXT NOT NULL,ScheduleValue TEXT NOT NULL,OutputFormat TEXT NOT NULL DEFAULT 'CSV',OutputPath TEXT,FilterJson TEXT,Enabled INTEGER DEFAULT 1,LastRun TEXT,NextRun TEXT,CreatedOn TEXT NOT NULL,CreatedBy TEXT);
CREATE TABLE IF NOT EXISTS ReportRecipients(Id INTEGER PRIMARY KEY AUTOINCREMENT,ScheduledReportId INTEGER NOT NULL,RecipientType TEXT NOT NULL DEFAULT 'File',Recipient TEXT NOT NULL,FOREIGN KEY(ScheduledReportId) REFERENCES ScheduledReports(Id) ON DELETE CASCADE,UNIQUE(ScheduledReportId,RecipientType,Recipient));
CREATE INDEX IF NOT EXISTS IX_ScheduledReports_Due ON ScheduledReports(Enabled,NextRun);
